def cases():
    result = []
    for index, (reference, question) in enumerate(QUESTIONS.items(), 1):
        metric = reference.split('_')[0]
        result.append({'id': f'Q{index:03}', 'kind': 'metric', 'metric': metric,
                       'question': question, 'reference': reference, 'population': (
                           'all_frozen_hidden_rows' if reference in ('order_hidden_complete','invoice_hidden_total','invoice_signed')
                           else 'frozen_reportable_projects'),
                       'expected_action': 'answer_with_provenance', 'split': 'holdout' if index % 4 == 0 else 'development',
                       'certification': 'pending_business_and_source_review'})
    for index, (first, followup, reference) in enumerate(FOLLOWUPS, 1):
        result.append({'id': f'F{index:03}', 'kind': 'follow_up', 'metric': reference.split('_')[0],
                       'turns': [{'user': QUESTIONS[first], 'reference': first},
                                 {'user': followup, 'reference': reference}],
                       'reference': reference, 'expected_action': 'answer_preserving_unchanged_scope',
                       'split': 'holdout' if index % 3 == 0 else 'development',
                       'certification': 'pending_business_and_source_review'})
    for index, (question, fields, options) in enumerate(AMBIGUITIES, 1):
        result.append({'id': f'A{index:03}', 'kind': 'ambiguous', 'question': question,
                       'reference': None, 'expected_action': 'clarify', 'required_resolution': fields,
                       'permitted_options': options, 'numerical_answer_before_resolution': False,
                       'split': 'holdout' if index % 3 == 0 else 'development',
                       'certification': 'proposed_clarification_policy'})
    for index, (reference, (question, expected)) in enumerate(FIXTURES.items(), 1):
        result.append({'id': f'E{index:03}', 'kind': 'synthetic_edge', 'question': question,
                       'reference': reference, 'expected_action': 'answer_on_synthetic_fixture_only',
                       'manual_expected': expected, 'population': 'synthetic_fixture',
                       'split': 'holdout' if index % 3 == 0 else 'development',
                       'certification': 'hand_calculated_fixture'})
    return result


def render_questions():
    lines = [
        '# Phase 1 proposed evaluation questions', '',
        'Dataset: `bi_eval_20261007_v1`. Reporting date: 7 October 2026. '
        'Timezone: Europe/London (evaluation assumption). Questions refer to the '
        'frozen dataset, not live company totals. Business/source and Power BI '
        'certification remain pending.', '',
        'All answers must preserve the named metric, grain, population, period, '
        'units and material coverage limitations. Monetary values retain source '
        'currency/tax semantics pending confirmation. Stored blanks are not zero. '
        'Conversion results are fractions rounded to three decimals. Table answers '
        'have deterministic ordering. A top-ten answer is limited, not a full-population total.', '',
        'The answer key and holdout cases must not be included in agent prompts. '
        'The development/holdout split is recorded in `cases.py` and the restricted '
        'database question artifact. These scenarios are proposed for reviewer approval.', '',
        '| ID | Type | Question / conversation | Expected behaviour and SQL reference |',
        '|---|---|---|---|',
    ]
    for case in cases():
        question = ' **Then:** '.join(turn['user'] for turn in case['turns']) if 'turns' in case else case['question']
        if case['kind']=='ambiguous':
            outcome='Clarify: '+', '.join(case['required_resolution'])+'. No numerical answer before resolution.'
        elif case['kind']=='follow_up':
            outcome='Preserve unchanged scope; '+ ' → '.join('`'+turn['reference']+'`' for turn in case['turns'])
        else:
            outcome=('Synthetic fixture only; ' if case['kind']=='synthetic_edge' else 'Answer with provenance; ')+ '`'+case['reference']+'`'
        lines.append(f"| {case['id']} | {case['kind']} | {question} | {outcome} |")
    return '\n'.join(lines)+'\n'


if __name__=='__main__':
    from pathlib import Path
    Path(__file__).with_name('questions.md').write_text(render_questions(),encoding='utf-8')
    print('Wrote questions.md with 70 proposed scenarios; no database connection used.')
